local function fmt_permissions(mode)
  local bits = { "r", "w", "x", "r", "w", "x", "r", "w", "x" }
  local result = {}
  for i = 8, 0, -1 do
    local bit = math.floor(mode / (2 ^ i)) % 2
    result[#result + 1] = bit == 1 and bits[9 - i] or "-"
  end
  return table.concat(result)
end

