    return lib.create(name, callback, opts or {})
  end
  return vim.api.nvim_create_user_command(name, callback, opts or {})
end

function M.del(name)
  pcall(vim.api.nvim_del_user_command, name)
end

function M.neotree(opts, config)
  opts = opts or {}
  opts.window = opts.window or {}
  opts.window.mappings = opts.window.mappings or {}
  local mappings = M.build_mappings(config)
  for k, v in pairs(mappings) do
    opts.window.mappings[k] = v
  end
  return opts
end

function M.teardown()
  for _, cmd_name in ipairs(_registered_commands) do
    usercmd.del(cmd_name)
  end
  _registered_commands = {}
end
